const q=s=>document.querySelector(s),safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stages=['Get started','Your business','Services & pricing','Finishing touches','Preview & publish'];
const categories={Photographer:{name:'Golden Hour Photography',area:'Austin + Texas Hill Country',price:'$4,200',services:'Wedding photography, Engagement sessions, Second photographer',bio:'Heartfelt imagery for the wildly in love. We capture candid moments and warm, true-to-life portraits for celebrations across Austin and the Texas Hill Country.',email:'hello@goldenhour.example',phone:'(512) 555-0142',website:'https://goldenhour.example',extraLabel:'When will couples receive their photos?',extra:'Sneak peeks within one week; full gallery in 8–10 weeks.'},DJ:{name:'Good Company DJs',area:'Austin + Central Texas',price:'$2,400',services:'Wedding DJ, Ceremony sound, MC services, Dance floor lighting',bio:'Great music. Full dance floors. We create a soundtrack that feels like you, from the first walk down the aisle to the last song of the night.',email:'hello@goodcompany.example',phone:'(512) 555-0188',website:'https://goodcompany.example',extraLabel:'What sound and setup equipment do you include?',extra:'Reception sound system, wireless microphones, and ceremony audio.'},Venue:{name:'Juniper Grove',area:'Dripping Springs, Texas',price:'$8,500',services:'Indoor and outdoor ceremonies, Reception hall, Getting-ready suites',bio:'A sunlit Hill Country gathering place with ancient oaks, open skies, and room for your favorite people.',email:'events@junipergrove.example',phone:'(512) 555-0166',website:'https://junipergrove.example',extraLabel:'What is your seated guest capacity?',extra:'Up to 180 seated guests.'},Caterer:{name:'Smoke & Honey Catering',area:'Austin + 60-mile service radius',price:'$85 per guest',services:'BBQ catering, Buffet service, Vegetarian menus, Late-night snacks',bio:'Slow-smoked favorites and generous Southern hospitality, served with a fresh seasonal twist. We bring people together over real good food.',email:'hello@smokeandhoney.example',phone:'(512) 555-0129',website:'https://smokeandhoney.example',extraLabel:'How do you accommodate dietary requirements?',extra:'Vegetarian and gluten-free menus available. Discuss allergies before booking.'}};
const empty=()=>({step:0,type:'Photographer',method:'',data:{},evidence:{},confirmedPrice:false,consent:false,reviewed:false,published:null,photo:'',insuranceName:'',sourceName:'',sample:false});let v=empty(),page='setup',busy=false,error='',insuranceFile=null;
try{const stored=JSON.parse(localStorage.getItem('bubs-vendor-selfserve-v1')||'null');if(stored&&categories[stored.type]&&stored.data){v={...empty(),...stored};v.step=Math.max(0,Math.min(7,Number(v.step)||0));}}catch{}
function save(){try{localStorage.setItem('bubs-vendor-selfserve-v1',JSON.stringify(v));return true}catch{notify('Browser storage is full or unavailable. Export a backup before leaving.');return false}}
function notify(s){q('#status').textContent=s;q('#status').className='show';setTimeout(()=>q('#status').className='',3500)}
const brand=()=>'<a class="brand" href="#setup"><i>♡</i><span>I Do!<small>WEDDING VENDOR STUDIO</small></span></a>';
function vendorTop(publicView=false){return `<header class="top">${brand()}<div class="top-right"><span class="small">${publicView?'A little closer to your people.':'YOUR VENDOR STUDIO'}</span>${publicView?'<button class="secondary" data-action="edit">Edit my listing</button>':'<button class="text" data-action="save-exit">Save & exit</button>'}</div></header>`}
function header(title,sub){return `<div class="intro"><span class="eyebrow">YOUR BUSINESS. YOUR NEXT CHAPTER.</span><h1>${title}</h1><p>${sub}</p></div>`}
function shell(content){return vendorTop()+`<div class="layout"><aside class="rail"><span class="eyebrow">Your listing, in bloom</span>${stages.map((s,i)=>`<button class="step ${v.step===i?'active':i<v.step?'done':''}" data-stage="${i}" ${busy?'disabled':''}><i>${i<v.step?'✓':i+1}</i>${s}</button>`).join('')}<div class="rail-foot"><span class="small">${required().length===0?'Ready for a final look':`${6-required().length} of 6 essentials added`}</span><div class="progress"><span style="width:${(6-required().length)/6*100}%"></span></div><p class="small">Your draft saves on this browser as you go.</p><button class="text" data-action="voice">Talk me through it ↗</button>${v.published?'<p><button class="text" data-action="view">View published listing</button></p>':''}<p class="quiet"><a href="team-demo.html">Presentation & evals ↗</a></p></div></aside><main class="workspace">${content}${error?`<p role="alert" class="error">${safe(error)}</p>`:''}</main></div>`}
function art(d=v.data,photo=v.photo){return `<div class="art">${photo?`<img src="${safe(photo)}" alt="Portfolio photograph for ${safe(d.name||'your business')}">`:'<span>for the moments<br>that become forever.</span>'}</div>`}
function mini(){return `<aside class="panel preview-mini">${art()}<section><span class="eyebrow">YOUR LISTING IS TAKING SHAPE</span><h3>${safe(v.data.name||'Your business, beautifully introduced.')}</h3><p class="small">${safe(v.data.area||'Your service area')}</p>${v.data.price?`<p style="margin-top:16px">From <b>${safe(v.data.price)}</b></p>`:''}<p class="small" style="margin-top:14px">Only public business details appear here. Your insurance document stays private.</p></section></aside>`}
function field(k,label,{full=false,type='text',hint='',optional=false}={}){const value=v.data[k]||'',proof=v.evidence[k];return `<div class="field ${full?'full':''}"><label for="vendor-${k}">${safe(label)}${optional?' <span class="small">(optional)</span>':''}</label>${type==='textarea'?`<textarea id="vendor-${k}" data-field="${k}">${safe(value)}</textarea>`:`<input id="vendor-${k}" data-field="${k}" type="${type}" value="${safe(value)}">`}${hint?`<div class="helper">${safe(hint)}</div>`:''}${proof?`<details class="source"><summary>${proof.value===value?'See where this came from':'Edited by you · original source'}</summary><blockquote>${safe(proof.quote)}</blockquote><span>${safe(proof.label)}</span>${proof.label.includes("Fictional")?` <a href="samples/vendor-${v.type.toLowerCase()}.txt" target="_blank">Open sample source packet ↗</a>`:""}</details>`:''}</div>`}
function actions(next='Continue →',back=true){return `<div class="actions">${back?'<button class="text" data-action="back">← Back</button>':'<span class="small">Saved on this browser</span>'}<button class="primary" data-action="next">${next}</button></div>`}
function startScreen(){return header('Meet your next<br><em>“we found you.”</em>','Create a listing that feels like your business. Start with what you have; we’ll help you bring the details together.')+`<div class="split"><section class="panel"><span class="eyebrow">01 / A GOOD PLACE TO START</span><h2 style="margin-top:12px">What do you bring to the celebration?</h2><div class="category-line">${Object.keys(categories).map(c=>`<button data-category="${c}" class="${v.type===c?'active':''}">${c==='DJ'?'DJ & entertainment':c==='Caterer'?'Catering':c}</button>`).join('')}</div><h3>How would you like to begin?</h3><div class="choices">${[['website','↗','Start with my website','Review a draft from your existing business details.'],['voice','◉','Talk me through it','Describe your business in a short conversation.'],['manual','✎','Start with a blank page','Write your details at your own pace.']].map(([key,icon,title,sub])=>`<button class="choice ${v.method===key?'selected':''}" data-method="${key}"><span class="icon">${icon}</span><span><strong>${title}</strong><small>${sub}</small></span><span class="arrow">→</span></button>`).join('')}</div>${v.method==='website'?`<div class="banner">Website import is simulated in this click-through demo. Use the fictional sample below to see traceable suggestions.</div><label for="source-url">Your website or portfolio</label><input id="source-url" type="url" value="${safe(v.sourceUrl||'')}" placeholder="https://yourbusiness.com"><div class="linkrow" style="margin-top:16px"><button class="text" data-action="sample">Try ${safe(categories[v.type].name)} →</button></div><button class="primary" style="margin-top:22px" data-action="import">Create my first draft →</button>`:v.method==='manual'?`<p style="margin-top:20px">A few essentials first. You can add a portfolio and supporting documents later.</p>${actions('Let’s get started →',false)}`:v.method==='voice'?`<p style="margin-top:20px">Use the local voice pilot to suggest your details. You review each change before adding it.</p><button class="primary" style="margin-top:20px" data-action="voice">Open my assistant →</button>${actions('Continue with my details →',false)}`:''}</section><aside class="note"><span class="eyebrow">FROM YOUR BUSINESS TO THEIR BIG DAY</span><h2 style="margin-top:15px">A thoughtful introduction.</h2><p>Your finished page brings your story, services, pricing, and portfolio into one place.</p><ul><li>Save and return at any point</li><li>Review every suggested detail</li><li>Preview exactly what couples will see</li></ul><p class="small">Fictional sample businesses · Browser-local demo publishing</p></aside></div>`}
function business(){return header('First, a proper<br><em>introduction.</em>','Tell couples who you are and where you work. These details will appear on your listing.')+`<div class="split"><section class="panel"><h2>Your business at a glance</h2>${v.sample?'<div class="banner">We drafted these details from the selected fictional source packet. Open the source notes, edit anything, and make it yours.</div>':''}<div class="fields">${field('name','Business name')}${field('area','Where do you serve?')}${field('bio','Introduce your business',{full:true,type:'textarea',hint:'Your style, your approach, and what makes working with you special.'})}${field('email','Public booking email',{type:'email',hint:'Couples will use this to contact your business.'})}${field('phone','Public booking phone',{type:'tel',optional:true})}${field('website','Website or portfolio',{type:'url',full:true,optional:true})}</div>${actions()}</section>${mini()}</div>`}
function services(){return header('The details that<br><em>make a match.</em>','Help couples understand what you offer, what it costs, and what to expect.')+`<div class="split"><section class="panel"><h2>Services & starting price</h2>${v.sample&&!v.confirmedPrice?`<div class="banner warn"><b>Is your website price still current?</b><p>The sample website lists ${safe(v.oldPrice)}. The more recent call says ${safe(categories[v.type].price)}. You choose what appears on your listing.</p><button class="text" data-action="current-price">Use ${safe(categories[v.type].price)} from the call</button></div>`:''}<div class="fields">${field('services','What can couples book you for?',{type:'textarea',full:true,hint:'Separate services with commas.'})}${field('price','Current starting price',{hint:v.type==='Caterer'?'Include the unit, such as $85 per guest.':'Include currency and any relevant unit, such as $4,200 per wedding.'})}${field('package','What does that starting price include?',{type:'textarea',full:true,optional:true})}${field('extra',categories[v.type].extraLabel,{type:'textarea',full:true,optional:true})}</div><div class="checkrow"><input id="price-confirm" type="checkbox" ${v.confirmedPrice?'checked':''}><label for="price-confirm">I confirm this is my current starting price. Final quotes may vary by event.</label></div>${actions()}</section>${mini()}</div>`}
function finishing(){return header('A little more you.<br><em>A little less guesswork.</em>','Add a photograph, check your documents, and decide what you’re ready to share.')+`<div class="split"><section class="panel"><h2>Give your listing a cover</h2><p>Upload one portfolio photograph that you have permission to display.</p><div class="upload"><label for="cover-upload">Cover photograph (optional)</label><input id="cover-upload" type="file" accept="image/jpeg,image/png,image/webp"><p class="helper">JPG, PNG or WebP · up to 2 MB. Compressed for this browser’s draft.</p>${v.photo?`<div class="art photo-preview"><img src="${safe(v.photo)}" alt="Your selected cover"></div><button class="text" data-action="remove-photo">Remove photograph</button>`:'<p class="helper">No photo yet? Your listing will use a decorative cover.</p>'}</div><hr class="divider"><h2>Insurance document</h2><p>Optional for this demo. This stays out of the couple-facing listing. Uploading does not verify coverage.</p><div class="upload"><label for="insurance-upload">Attach a certificate</label><input id="insurance-upload" type="file" accept="application/pdf,image/jpeg,image/png"><p class="helper">PDF, JPG or PNG · up to 5 MB. Attachment available only during this page session.</p>${v.insuranceName?`<p class="filename">${insuranceFile?'Attached this session':'Previously selected (reattach to view)'}: ${safe(v.insuranceName)}</p>${insuranceFile?'<button class="text" data-action="view-insurance">View attachment ↗</button>':''}`:''}<p><a class="small" href="samples/golden-hour-sample-certificate.pdf" download>Download fictional sample certificate ↓</a></p></div><div class="checkrow"><input id="publish-consent" type="checkbox" ${v.consent?'checked':''}><label for="publish-consent">I’m authorized to represent this business and publish the business details and images I provide.</label></div>${actions('Preview my listing →')}</section><aside class="note"><span class="eyebrow">PUBLIC OR PRIVATE?</span><h3 style="margin-top:12px">You control the introduction.</h3><ul><li>Public: business story, service area, pricing, booking contacts, portfolio</li><li>Private: insurance attachment</li></ul><p class="small">This demo saves your draft and cover in this browser. It does not upload your documents to a server.</p></aside></div>`}
function required(){return ['name','area','bio','email','services','price'].filter(k=>!String(v.data[k]||'').trim())}
function errorsFor(step){if(step===1){if(['name','area','bio','email'].some(k=>!v.data[k]?.trim()))return 'Add your business name, service area, introduction, and booking email.';if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.data.email))return 'Enter a valid public booking email.';if(v.data.website&&!validUrl(v.data.website))return 'Use an https:// or http:// website address.'}if(step===2){if(!v.data.services?.trim()||!v.data.price?.trim())return 'Add your services and starting price.';if(!v.confirmedPrice)return 'Confirm your current starting price before continuing.'}if(step===3&&!v.consent)return 'Confirm that you’re authorized to publish these business details.';return ''}
function validUrl(url){try{return ['https:','http:'].includes(new URL(url).protocol)}catch{return false}}
function listing(d,photo,published=false,listingType=v.type,isSample=v.sample){return `${art(d,photo)}<div class="listing-title"><div><span class="eyebrow">${safe(listingType)} · ${safe(d.area)}</span><h1>${safe(d.name||'Your business name')}</h1></div><span class="badge">${published?'Demo listing · Published':'Your listing preview'}</span></div><div class="listing-grid"><section><h2>A little about us</h2><p>${safe(d.bio||'Your introduction will appear here.')}</p><hr class="divider"><h2>For your celebration</h2><div class="services">${(d.services||'Your services').split(',').filter(x=>x.trim()).map(s=>`<span>${safe(s.trim())}</span>`).join('')}</div>${d.package?`<p style="margin-top:22px">${safe(d.package)}</p>`:''}${d.extra?`<hr class="divider"><h2>${safe(categories[listingType].extraLabel)}</h2><p>${safe(d.extra)}</p>`:''}<hr class="divider"><span class="eyebrow">WHERE WE CELEBRATE</span><p style="margin-top:12px">${safe(d.area)}</p></section><aside><div class="panel public-card"><span class="eyebrow">LET’S MAKE SOMETHING GOOD</span><p style="margin-top:18px">Starting at</p><strong>${safe(d.price||'Price to come')}</strong><p class="small">${d.package?safe(d.package):'Contact us for a quote tailored to your celebration.'}</p>${published?`<button class="primary" data-action="inquire">Ask about your date ↗</button>`:'<button class="primary" disabled>Ask about your date ↗</button>'}<p class="small">${safe(d.email||'Your booking email')}</p>${d.phone?`<p class="small">${safe(d.phone)}</p>`:''}${d.website&&validUrl(d.website)?`<p style="margin-top:14px"><a href="${safe(d.website)}" target="_blank" rel="noopener">Visit our website ↗</a></p>`:''}<p class="quiet">${isSample?'Fictional business · Contact actions are simulated.':'Browser-local demonstration listing.'}</p></div></aside></div>`}
function preview(){const missing=required();return header('Take a look.<br><em>Then take your bow.</em>','This is how couples will see your business. Review it once more before you publish.')+`<div class="panel">${missing.length?`<div class="banner warn">${missing.length} essentials missing: ${safe(missing.join(', '))}. <button class="text" data-stage="1">Finish my details</button></div>`:''}<div class="listing" style="padding:0">${listing(v.data,v.photo)}</div><hr class="divider"><div class="checkrow"><input type="checkbox" id="review-confirm" ${v.reviewed?'checked':''}><label for="review-confirm">I’ve reviewed this preview and confirm the public information is accurate.</label></div><p class="small">Publish creates a finished demo listing saved in this browser. It does not make your details publicly accessible on the internet.</p><div class="actions"><button class="text" data-action="back">← Keep editing</button><button class="primary" data-action="publish">${v.published?'Publish my changes':'Publish my listing'} →</button></div></div>`}
function published(){const p=v.published;return vendorTop(true)+`<div class="publish-ok"><span>✓ Your demo listing is published. ${p.date?`Updated ${safe(new Date(p.date).toLocaleDateString())}.`:''}</span><button class="text" data-action="export">Export listing ↓</button></div><main class="listing">${listing(p.data,p.photo,true,p.type,p.sample)}<p class="quiet">Saved on this browser · Not a publicly hosted vendor listing</p></main>`}
function render(){q('#vendor-app').innerHTML=page==='listing'&&v.published?published():page==='saved'?vendorTop()+`<main class="saved-screen"><span class="eyebrow">WE’LL KEEP YOUR PLACE</span><h1>Your next chapter<br>can wait a moment.</h1><p>Your draft is saved on this browser. Come back when you’re ready.</p><button class="primary" data-action="resume">Continue my listing →</button><p class="quiet">Using a different device? Export a draft backup before you leave.</p><button class="text" data-action="export">Export draft ↓</button></main>`:shell([startScreen,business,services,finishing,preview][v.step]());bindVendor()}
function navigate(step){if(busy)return;v.step=step;error='';save();render();window.scrollTo(0,0)}
async function importSample(){if(!v.sample||v.sourceUrl!==categories[v.type].website){error='Live website extraction isn’t enabled in this demo. Choose the sample business, or start with a blank page for your own details.';render();return}busy=true;error='';q('#vendor-app').innerHTML=shell(header('Gathering the pieces.','Preparing a first draft from the fictional source packet.')+'<section class="panel loading" role="status"><div class="spinner"></div><h2>Your business, coming together.</h2><ul id="load-steps"><li class="on">Reading your business introduction</li><li>Organizing services and contact details</li><li>Flagging pricing for your review</li></ul><p class="small">Simulated import · No external website is fetched</p></section>');for(let n=0;n<3;n++){await new Promise(r=>setTimeout(r,1600));document.querySelectorAll('#load-steps li').forEach((x,i)=>x.classList.toggle('on',i<=n))}const s=categories[v.type];v.data={name:s.name,area:s.area,bio:s.bio,services:s.services,price:({'Photographer':'$3,800','DJ':'$2,000','Venue':'$7,500','Caterer':'$75 per guest'})[v.type],website:s.website,phone:s.phone,email:'',extra:s.extra};v.oldPrice=v.data.price;v.evidence={};for(const k of ['name','area','bio','services','price','website','phone','extra'])v.evidence[k]={value:v.data[k],quote:v.data[k],label:k==='extra'?'Fictional recent call transcript':'Fictional website snapshot'};v.confirmedPrice=false;v.consent=false;v.reviewed=false;busy=false;navigate(1);notify('Your first draft is ready. Add the missing booking email and review pricing.')}
async function openVoice(){save();const modal=q('#assistant'),frame=q('#voice-frame');frame.src='voice-setup.html#voice';modal.showModal();frame.onload=()=>frame.contentWindow.postMessage({type:'bubs-vendor-context',data:v.data,category:v.type},location.origin)}
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==q('#voice-frame').contentWindow||e.data?.type!=='bubs-vendor-updates')return;const allowed=typeof BubsVendorContract!=='undefined'?BubsVendorContract.keysForCategory(v.type):typeof vendorGroups!=='undefined'?vendorGroups.flatMap(g=>Object.keys(g.fields)):['name','area','bio','email','phone','website','services','price','extra'];for(const k of allowed){if(typeof e.data.data?.[k]==='string'){const val=e.data.data[k].slice(0,2000);if(val!==v.data[k]){v.data[k]=val;if(['package1','price','includes1','package2','price2','includes2','package3','price3','includes3','overtime','travel','tax'].includes(k))v.confirmedPrice=false;if(k==='delivery')v.confirmedDelivery=false;if(v.sectionReviews&&typeof intakeFields==='function'){for(let section=1;section<=6;section++)if(k in intakeFields(section))v.sectionReviews[section]=false}v.reviewed=false;}const proof=e.data.evidence?.[k];if(proof)v.evidence[k]={value:val,quote:String(proof.evidence||'').slice(0,1000),label:'Your conversation · Applied by you'};}}save();render();notify('Applied assistant details added to your draft.')});
q('#close-assistant').onclick=()=>{q('#voice-frame').contentWindow.postMessage({type:'bubs-end-voice'},location.origin);q('#assistant').close()};q('#assistant').addEventListener('cancel',()=>q('#voice-frame').contentWindow.postMessage({type:'bubs-end-voice'},location.origin));
function exportDraft(){const data=page==='listing'?v.published:{category:v.type,data:v.data};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='bubs-my-listing.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function bindVendor(){document.querySelectorAll('[data-field]').forEach(el=>el.oninput=()=>{v.data[el.dataset.field]=el.value;v.reviewed=false;if(el.dataset.field==='price')v.confirmedPrice=false;save();if(el.dataset.field==='price'&&q('#price-confirm'))q('#price-confirm').checked=false});document.querySelectorAll('[data-stage]').forEach(el=>el.onclick=()=>navigate(Number(el.dataset.stage)));document.querySelectorAll('[data-category]').forEach(el=>el.onclick=()=>{if(v.type===el.dataset.category)return;if(Object.keys(v.data).length&&!confirm('Changing category starts a fresh draft. Your published listing, if any, stays available until you publish again. Continue?'))return;const published=v.published;v=empty();v.published=published;v.type=el.dataset.category;save();render()});document.querySelectorAll('[data-method]').forEach(el=>el.onclick=()=>{v.method=el.dataset.method;error='';save();render()});if(q('#source-url'))q('#source-url').oninput=e=>{v.sourceUrl=e.target.value;save()};if(q('#price-confirm'))q('#price-confirm').onchange=e=>{v.confirmedPrice=e.target.checked;v.reviewed=false;save()};if(q('#publish-consent'))q('#publish-consent').onchange=e=>{v.consent=e.target.checked;save()};if(q('#review-confirm'))q('#review-confirm').onchange=e=>{v.reviewed=e.target.checked;save()};if(q('#cover-upload'))q('#cover-upload').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>2097152){notify('Choose a JPG, PNG or WebP under 2 MB.');return}try{const image=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,1400/image.width);canvas.width=image.width*scale;canvas.height=image.height*scale;canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);v.photo=canvas.toDataURL('image/jpeg',.8);image.close();v.reviewed=false;save();render()}catch{notify('This image could not be opened. Try another file.')}};if(q('#insurance-upload'))q('#insurance-upload').onchange=e=>{const f=e.target.files[0];if(!f)return;if(!['application/pdf','image/jpeg','image/png'].includes(f.type)||f.size>5242880){notify('Choose a PDF, JPG or PNG under 5 MB.');return}insuranceFile=f;v.insuranceName=f.name;save();render()};document.querySelectorAll('[data-action]').forEach(el=>el.onclick=async()=>{const a=el.dataset.action;if(a==='sample'){v.sample=true;v.sourceUrl=categories[v.type].website;save();render()}if(a==='import')importSample();if(a==='next'){error=errorsFor(v.step);if(error){render();return}navigate(Math.min(7,v.step+1))}if(a==='back')navigate(Math.max(0,v.step-1));if(a==='current-price'){v.data.price=categories[v.type].price;v.evidence.price={value:v.data.price,quote:`Our current starting price is ${v.data.price}.`,label:'Selected fictional introductory call'};v.confirmedPrice=true;v.reviewed=false;save();render()}if(a==='save-exit'){if(save()){page='saved';render();window.scrollTo(0,0)}}if(a==='resume'){page='setup';render()}if(a==='voice')openVoice();if(a==='remove-photo'){v.photo='';v.reviewed=false;save();render()}if(a==='view-insurance'&&insuranceFile){const url=URL.createObjectURL(insuranceFile);window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000)}if(a==='publish'){error=[1,2,3,4,5,6].map(errorsFor).find(Boolean)||(required().length?'Complete the onboarding requirements.':'')||(!v.reviewed?'Confirm that you’ve reviewed the preview.':'');if(error){render();return}v.published={type:v.type,sample:v.sample,data:publicVendorData(v.data),photo:v.photo,date:new Date().toISOString()};if(!save())return;page='listing';location.hash='listing';render();window.scrollTo(0,0);notify('Your demo listing is published.')}if(a==='edit'){page='setup';navigate(1);location.hash='setup'}if(a==='view'){page='listing';location.hash='listing';render();window.scrollTo(0,0)}if(a==='export')exportDraft();if(a==='inquire'){notify(v.published.sample?'Demo inquiry: couples would contact you here. No message was sent.':'Your booking email is '+v.published.data.email+'. No message was sent.')}})}
